def parse(qs):
    """Parse a URL query string into a dictionary."""
    if qs == "":
        return {}

    # Split the query string on '&'
    segments = qs.split('&')

    # Initialize the result dictionary
    result = {}

    for segment in segments:
        # Check if there's an '=' to split the segment
        if '=' in segment:
            key, value = segment.split('=', 1)
        else:
            key, value = segment, ''

        # Update the result dictionary
        result[key] = value

    return result

