def parse_encoded(qs):
    """Parse a URL-encoded query string into a dictionary."""
    if qs == "":
        return {}

    # Split the query string on '&'
    segments = qs.split('&')

    # Decode each key and value
    decoded_segments = [(urllib.parse.unquote(key), urllib.parse.unquote(value)) for key, value in [segment.split('=', 1) for segment in segments]]

    # Initialize the result dictionary
    result = {}

    for key, value in decoded_segments:
        # Update the result dictionary
        result[key] = value

    return result

