        del self.cache[tail.key]
        if tail.prev:
            tail.prev.next = None
        else:
            self.head = None
        self.tail = tail.prev

    def _update_cache_position(self, node):
        # Move the node to the head of the cache while maintaining its current position
        if node != self.head:
            node.prev.next = node.next
            node.next.prev = node.prev
            self._add_to_head(node)

