def fold(lines):
    result = []
    current_line = ""

    for line in lines:
        if line.startswith(" ") or line.startswith("\t"):
            # Continuation of the previous line
            current_line += line.lstrip()
            if not result or result[-1].endswith(" "):
                result[-1] += current_line.strip()
            else:
                result.append(current_line.strip())
        else:
            # Start of a new line
            if current_line:
                result.append(current_line.strip())
            current_line = line

    # Append any remaining content in current_line
    if current_line:
        result.append(current_line.strip())

    return result

