                current_line.append(word)

    # Ensure the last line does not end with an article
    if current_line:
        last_word = current_line[-1]
        if len(last_word) == 1 and last_word.lower() in {'a', 'an', 'the'}:
            lines.append(' '.join(current_line[:-1]))
            current_line = [last_word]

    # Ensure the last line does not exceed width
    if current_line:
        lines.append(' '.join(current_line))

    return lines
